// Build the Gate 1 message. Each job gets two links back into this
// workflow's resume webhook - clicking one records pursue or skip.
const d = $input.first().json;
const jobs = d.jobs || [];
if (!jobs.length) {
  return [{ json: { empty: true, html: '<p>No jobs surfaced today.</p>', count: 0 } }];
}
const resume = $execution.resumeUrl;
const rows = jobs.map((j, i) => {
  const amb = j.archetype_confident === false ? ' <i>(ambiguous)</i>' : '';
  return `<tr>
    <td style="padding:8px 6px;border-bottom:1px solid #eee;vertical-align:top">
      <b>${i + 1}. ${j.title || ''}</b><br>
      <span style="color:#555;font-size:13px">${j.company || '?'} &middot; ${j.location || 'location unstated'} &middot; via ${j.source}</span><br>
      <span style="color:#555;font-size:13px">${j.archetype || '?'}${amb} &middot; batch score ${j.score}/100</span><br>
      <a href="${j.url}" style="font-size:13px">open posting</a>
      &nbsp;|&nbsp; <a href="${resume}?slug=${encodeURIComponent(j.slug)}&verdict=pursue">pursue</a>
      &nbsp;|&nbsp; <a href="${resume}?slug=${encodeURIComponent(j.slug)}&verdict=skip">skip</a>
    </td></tr>`;
}).join('');
const html = `<div style="font-family:system-ui,sans-serif;max-width:720px">
  <h2 style="font-size:17px">${jobs.length} job(s) — ${new Date().toISOString().slice(0, 10)}</h2>
  <p style="color:#555;font-size:13px">Rank is meaningful; the score is relative to this batch only.
  An <i>ambiguous</i> archetype means the top two were within 30% of each other.</p>
  <table style="border-collapse:collapse;width:100%">${rows}</table>
  <p style="color:#777;font-size:12px">Gate 1. Every choice is also a training label —
  the ranker needs roughly 150 before it can be tuned against your judgement.</p>
</div>`;
return [{ json: { empty: false, html, count: jobs.length } }];
